mapper.select:
SELECT
    (SELECT COUNT(*)
     FROM recipes
     WHERE recipes.group_id = #{groupId}


                AND EXISTS (
                    SELECT 1
                    FROM users recipe_users
                    WHERE recipe_users.id = recipes.user_id
                      AND recipe_users.household_id = #{householdId}
                )


                AND NOT EXISTS (
                    SELECT 1
                    FROM users recipe_users
                    WHERE recipe_users.id = recipes.user_id
                      AND recipe_users.household_id IS NOT NULL
                )

        ) AS total_recipes,
    (SELECT COUNT(*) FROM users WHERE group_id = #{groupId}

            AND household_id = #{householdId}
            AND household_id IS NULL
        ) AS total_users,
    (SELECT COUNT(*) FROM categories WHERE group_id = #{groupId}) AS total_categories,
    (SELECT COUNT(*) FROM tags WHERE group_id = #{groupId}) AS total_tags,
    (SELECT COUNT(*) FROM tools WHERE group_id = #{groupId}) AS total_tools
